"""Input/accessibility/storage boundaries; unlock-only fixtures are separate from8map campaign."""
import argparse,asyncio,datetime,json,math
from playwright.async_api import async_playwright
from test_echo_browser import ROOT,KEY,FIELDS,snap,watch,load,begin,complete,Pilot,Driver,click,invariant
async def main(args):
 out=ROOT/args.out;out.mkdir(parents=True,exist_ok=True);errors=[];bad=[];failed=[];checks=[];contexts=[];report={'testedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':args.url,'method':'Real keys, mouse drag, native touch and ordinary combat. Only storage metadata/denied-storage boundary fixtures are injected; no combat fields or clocks/results written.','checks':checks};pilot=await Pilot().start()
 def save():report.update(consoleErrors=errors,badResponses=bad,requestFailures=failed);(out/'report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 async with async_playwright() as pw:
  b=await pw.chromium.launch()
  async def fresh(tutorial=True,touch=False,raw=None,denied=False,keyboard=False):
   for old in contexts:await old.close()
   contexts.clear()
   ctx=await b.new_context(viewport={'width':390 if touch else 1440,'height':900},is_mobile=touch,has_touch=touch);contexts.append(ctx)
   if denied:await ctx.add_init_script("Storage.prototype.getItem=()=>{throw new DOMException('Denied','SecurityError')};Storage.prototype.setItem=()=>{throw new DOMException('Denied','SecurityError')}")
   else:
    value=raw if raw is not None else json.dumps({'version':1,'unlocked':1,'last':1,'tutorialSeen':tutorial,'turnRate':2.2,'bob':False,'guide':True,'sound':False,'best':{},'resume':None});await ctx.add_init_script('if(!sessionStorage.getItem("echo-fixture")){localStorage.setItem('+json.dumps(KEY)+','+json.dumps(value)+');sessionStorage.setItem("echo-fixture","1")}')
   p=await ctx.new_page();watch(p,errors,bad,failed);await load(p,args.url);return p,await Driver(p,touch,keyboard).start()
  try:
   p,d=await fresh(tutorial=False);s=await snap(p);assert await p.locator('#help-dialog').is_visible() and s['state']=='ready' and s['ticks']==0;await p.wait_for_timeout(100);assert (await snap(p))['ticks']==0;await click(p,'#help-confirm');checks.append('First tutorial and ready state do not advance simulation');save()
   assert (await snap(p))['prefs']=={'turnRate':2.2,'bob':False,'guide':True,'sound':False};assert await p.evaluate('document.pointerLockElement===null');checks.append('Default motion bob off, ordinary pointer drag available, no pointer lock');save()
   await click(p,'#levels');assert await p.locator('[data-level="8"]').is_disabled();await click(p,'#levels-close');checks.append('Fresh eighth level locked; book close returns to ready');save()
   colors=await p.locator('#view').evaluate('(c)=>{const d=c.getContext("2d").getImageData(0,0,c.width,c.height).data,s=new Set();for(let i=0;i<d.length;i+=400)s.add(`${d[i]},${d[i+1]},${d[i+2]}`);return s.size}');assert colors>10;checks.append('Actual first-person canvas raycast scene renders multiple wall/floor/sprite colors');save()
   await begin(p,d);before=await snap(p);await d.look(.2,before['turnRate']);after=await snap(p);assert abs(math.atan2(math.sin(after['player']['yaw']-before['player']['yaw']),math.cos(after['player']['yaw']-before['player']['yaw']))-.2)<.01;assert math.hypot(after['player']['x']-before['player']['x'],after['player']['y']-before['player']['y'])<.01;checks.append('Real bounded canvas drag turns viewpoint without position teleport');save()
   for rate in [1.4,3]:
    await p.locator('#turn-rate').select_option(str(rate));await p.locator('#view').focus();before=await snap(p);await p.keyboard.down('ArrowRight');await p.wait_for_timeout(300);await p.keyboard.up('ArrowRight');after=await snap(p);delta=math.atan2(math.sin(after['player']['yaw']-before['player']['yaw']),math.cos(after['player']['yaw']-before['player']['yaw']));turns=[c for c in after['log'] if c['kind']=='controls'][-2:];assert turns[0]['turn']==1 and turns[1]['turn']==0;assert abs(delta-(turns[1]['tick']-turns[0]['tick'])/60*rate)<1e-6
   await p.locator('#turn-rate').select_option('2.2');checks.append('Slow and fast settings change real keyboard rotation at declared rates');save()
   await p.locator('#bob').check();await p.locator('#guide').uncheck();saved=await p.evaluate('(k)=>JSON.parse(localStorage.getItem(k))',KEY);assert saved['bob'] and not saved['guide'];await p.locator('#bob').uncheck();await p.locator('#guide').check();checks.append('Bob and route assist are separate optional persisted visual controls');save()
   await p.locator('#view').focus();await p.keyboard.press('e');await p.wait_for_timeout(130);assert '靠近门或出口' in await p.locator('#message').inner_text();checks.append('Out-of-range interaction gives clear feedback without spending ammo');save()
   await p.keyboard.down('w');await p.wait_for_timeout(100);await p.keyboard.press('p');await d.release();s=await snap(p);assert s['state']=='paused' and not any(s['controls'].values());await p.wait_for_timeout(300);after=await snap(p);assert all(s[k]==after[k] for k in FIELDS);await p.keyboard.press('p');checks.append('Pause releases held movement/fire and freezes22 complete fields');save()
   await click(p,'#help');assert (await snap(p))['state']=='paused';await click(p,'#help-close');await p.wait_for_function('window.__echo.snapshot().state==="playing"');await click(p,'#levels');assert (await snap(p))['state']=='paused';await click(p,'#levels-close');await p.wait_for_function('window.__echo.snapshot().state==="playing"');checks.append('Help and level book pause and resume without stale held inputs');save()
   await click(p,'#sound');assert await p.locator('#sound').get_attribute('aria-pressed')=='true';await click(p,'#sound');checks.append('Original synthesized sound can be toggled and persisted');save()
   await click(p,'#reset');await begin(p,d);await p.keyboard.down('s');await p.wait_for_timeout(900);await p.keyboard.up('s');s=await snap(p);invariant(s);assert s['player']['x']>=1.18-1e-8 and s['player']['y']>=1.18-1e-8;checks.append('Actual held movement cannot leave outer walls');save()
   # Facing the outer wall: firing is intentionally spent, not a combat-state fixture.
   await p.keyboard.down('Space');await p.wait_for_timeout(2600);await p.keyboard.up('Space');s=await snap(p);assert s['player']['ammo']==0 and s['stats']['fired']==8;await p.keyboard.press('j');assert (await snap(p))['stats']['fired']==8;invariant(s);checks.append('Held wall fire uses exactly8 finite rounds; empty fire and repeat input cannot create ammo');save()
   await click(p,'#log-toggle');assert await p.locator('#history li').count()==len((await snap(p))['events']);checks.append('Expanded log exposes one warning/hit/pickup/open event per settlement');save()
   p,d=await fresh();await begin(p,d);warn,_,_=await complete(p,pilot,d,stop=lambda s:any(e['action'] for e in s['enemies']));await d.release();assert any(e['action'] for e in warn['enemies']);await p.wait_for_timeout(130);assert '蓄光' in await p.locator('#warning').inner_text();await p.wait_for_function('window.__echo.snapshot().player.hp<100');hurt=await snap(p);assert hurt['player']['hp']>0 and hurt['stats']['damageTaken']>0;end,_,_=await complete(p,pilot,d);await d.release();assert end['state']=='won' and end['stats']['healed']>0 and end['player']['hp']<=100;report['ordinaryHitHeal']={k:end[k] for k in ['player','ledger','stats','log']};checks.append('Visible normal warning causes real damage when ignored; ordinary route pickup heals actual bounded HP before win');save()
   best=end['best'];await click(p,'#secondary-action');s=await snap(p);assert s['state']=='ready' and s['player']['hp']==100 and s['player']['ammo']==8 and s['best']==best;checks.append('Retry resets authored budget and retains earned best/unlock');save()
   await begin(p,d);await p.keyboard.down('w');await p.wait_for_timeout(150);await p.evaluate('window.dispatchEvent(new Event("blur"))');await p.keyboard.up('w');s=await snap(p);assert s['state']=='paused' and not any(s['controls'].values());await p.wait_for_timeout(200);after=await snap(p);assert all(s[k]==after[k] for k in FIELDS);checks.append('Window blur auto-pauses and clears held inputs without movement backlog');save()
   p,d=await fresh(raw='{broken');assert (await snap(p))['state']=='ready';checks.append('Malformed storage falls back to playable normal setup');save()
   forged={'version':1,'unlocked':1,'last':1,'tutorialSeen':True,'resume':{'version':1,'level':1,'ticks':0,'commands':[],'player':{'x':9,'hp':999,'ammo':999}}};p,d=await fresh(raw=json.dumps(forged));s=await snap(p);assert s['state']=='paused' and s['player']['hp']==100 and s['player']['ammo']==8 and s['player']['x']==1.5;checks.append('Forged checkpoint positions/HP/ammo ignored; only legal log reconstructs state');save()
   p,d=await fresh(denied=True);assert (await snap(p))['storageAvailable'] is False and await p.locator('#storage-note').is_visible();await begin(p,d);end,_,_=await complete(p,pilot,d);await d.release();assert end['state']=='won';checks.append('Denied storage still supports complete ordinary first level');save()
   p,d=await fresh(keyboard=True);await begin(p,d);end,_,_=await complete(p,pilot,d);await d.release();assert end['state']=='won';checks.append('Full first level through keyboard walk/turn/fire/use, without mouse look');save()
   for width in [320,360,390,768,1024,1440]:
    await p.set_viewport_size({'width':width,'height':900});assert not await p.evaluate('document.documentElement.scrollWidth>innerWidth');await click(p,'#help');assert not await p.locator('#help-dialog').evaluate('(e)=>e.scrollWidth>e.clientWidth');await p.screenshot(path=str(out/f'width-{width}.png'));await click(p,'#help-close')
   checks.append('Six widths320–1440 and handbook/result controls fit without page overflow');save()
   p,d=await fresh(touch=True);await begin(p,d);end,_,_=await complete(p,pilot,d);await d.release();assert end['state']=='won';report['nativeTouch']={k:end[k] for k in ['player','stats','log','score']};await p.screenshot(path=str(out/'native-touch-win.png'),full_page=True);checks.append('Native touchscreen holds and drags plus real door/exit taps complete normal first level');save()
   p,d=await fresh();await begin(p,d);warn,_,_=await complete(p,pilot,d,stop=lambda s:any(e['action'] for e in s['enemies']));await d.release();await p.wait_for_function('window.__echo.snapshot().state==="lost"',timeout=100000);end=await snap(p);assert end['player']['hp']==0 and end['stats']['settlements']==1;before=end['stats']['fired'];await p.keyboard.press('Space');await p.keyboard.press('e');assert (await snap(p))['stats']['fired']==before;await click(p,'#primary-action');s=await snap(p);assert s['state']=='ready' and s['player']['hp']==100 and s['player']['ammo']==8;checks.append('Actual undefended normal enemy beams cause death once; terminal inputs reject and retry restores normal resources');save()
   assert not errors and not bad and not failed,(errors,bad,failed);report['passed']=True;save();print(json.dumps({'passed':True,'groups':len(checks)}))
  except Exception as e:report['error']=type(e).__name__+': '+str(e)[:1800];raise
  finally:
   save()
   for c in contexts:await c.close()
   await b.close();await pilot.close()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--url',default='http://127.0.0.1:4174/games/echo/');a.add_argument('--out',default='.local/echo-ui');asyncio.run(main(a.parse_args()))
